import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Stocks","description":"","frontmatter":{"title":"Stocks"},"headers":[],"relativePath":"language-reference/stocks.md","filePath":"language-reference/stocks.md"}'),i={name:"language-reference/stocks.md"};function o(l,e,p,c,r,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="stocks" tabindex="-1">Stocks <a class="header-anchor" href="#stocks" aria-label="Permalink to &quot;Stocks&quot;">​</a></h1><p>Simple systems can be expressed accurately as linear relationships--straight forward cause and effect. More complex systems, however, transform those linear relationships into dynamic feedback loops where change to one variable&#39;s value impacts several different parts of the system.</p><p>Our state chart is that simple system, states are either on or off. But when specifying what triggers them to go on or off we end up with a dynamic system instead.</p><p>Stocks are the first building block of a dynamic system. They are resevoirs of resources. In our REPL model we care about two scenarios:</p><ol><li>That the orchestrator goes from pulling the container to standing it up correctly</li><li>That the cache always has enough memory to store references to active servers.</li></ol><p>So to do that we create the following stocks</p><p>For the cache</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def resources = stock{</span></span>
<span class="line"><span>    blocks: 0, // Used blocks of memory</span></span>
<span class="line"><span>    table: 0, // Number of items in the table</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>For the orchestrator</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def pool = stock{</span></span>
<span class="line"><span>    instances: 0,</span></span>
<span class="line"><span>    loading: 0,</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="possible-values" tabindex="-1">Possible Values <a class="header-anchor" href="#possible-values" aria-label="Permalink to &quot;Possible Values&quot;">​</a></h2><p>In Fault, stocks can be numeric values (floats or integers), booleans, or unknown/uncertain types.</p><p>The Fault compiler treats all numeric values as doubles (Real numbers in SMT, essentially floats) in order to be friendlier to the solver.</p><p>For more information about different types of values <a href="./../data-types/">see the section on data types</a></p><h2 id="stock-inheritance" tabindex="-1">Stock Inheritance <a class="header-anchor" href="#stock-inheritance" aria-label="Permalink to &quot;Stock Inheritance&quot;">​</a></h2><p>A stock can inherit all fields from another stock using <code>extends</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def base = stock{</span></span>
<span class="line"><span>    value: 0,</span></span>
<span class="line"><span>    limit: 100,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def extended = stock{</span></span>
<span class="line"><span>    extends base,</span></span>
<span class="line"><span>    extra: 5,</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>extended</code> has all three fields: <code>value</code>, <code>limit</code>, and <code>extra</code>.</p><p>To inherit from a stock in an imported spec, qualify the name with the import alias:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def level2 = stock{</span></span>
<span class="line"><span>    extends nestedimport.level1,</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="excluding-inherited-fields" tabindex="-1">Excluding Inherited Fields <a class="header-anchor" href="#excluding-inherited-fields" aria-label="Permalink to &quot;Excluding Inherited Fields&quot;">​</a></h3><p>Use <code>exclude</code> to drop a specific field from the inherited set:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def derived = stock{</span></span>
<span class="line"><span>    extends base,</span></span>
<span class="line"><span>    exclude limit,</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>derived</code> has <code>value</code> but not <code>limit</code>. This lets you build variations of a stock without duplicating the common fields.</p>`,24)])])}const m=s(i,[["render",o]]);export{u as __pageData,m as default};
